//! Parity with Go, from fixtures generated by the Go packages
//! (`tests/golden/gen_go_cursor_*.go.txt`). The pin and the attribution
//! anchors are compared byte for byte, so a Go re-pin that is not mirrored
//! here (R13) fails this suite.

use serde_json::{Value, json};

use crate::attribution::*;
use crate::client::*;
use crate::connect::parse_connect_error;
use crate::context::{VENDOR_ORDER, base_context_window, limits_for, vendor};
use crate::events::{decode_frame, parse_interaction_type};
use crate::install::{
    BRIDGE_ARCHIVE_PREFIX, PINNED_SDK_VERSION, PYPI_PROJECT_JSON, pypi_pinned_project,
};
use crate::turn::{Turn, TurnSpec, scale_cursor_meter_usage};

fn pkg() -> Value {
    serde_json::from_str(include_str!("../tests/golden/go_cursor_pkg.json")).unwrap()
}

fn engine() -> Value {
    serde_json::from_str(include_str!("../tests/golden/go_cursor_engine.json")).unwrap()
}

/// Text with an optional JSON tail (`prefix {…}`), the tail as a value.
fn json_tail(t: &str) -> (&str, Value) {
    let at = t.find(['{', '[']).unwrap_or(t.len());
    let tail = serde_json::from_str(&t[at..]).unwrap_or_else(|_| json!(&t[at..]));
    (&t[..at], tail)
}

fn s(v: &Value) -> &str {
    v.as_str().unwrap_or_else(|| panic!("not a string: {v}"))
}

#[test]
fn pin_and_anchors_match_go() {
    let g = pkg();
    assert_eq!(
        PINNED_SDK_VERSION,
        s(&g["pinnedSDKVersion"]),
        "re-pin both sides together"
    );
    assert_eq!(pypi_pinned_project(), s(&g["pypiPinnedProject"]));
    assert_eq!(PYPI_PROJECT_JSON, s(&g["pypiProjectJSON"]));
    assert_eq!(BRIDGE_ARCHIVE_PREFIX, s(&g["bridgeArchivePrefix"]));
    let pairs = |a: Vec<Anchor>| -> Vec<(String, String)> {
        a.into_iter().map(|a| (a.old.to_owned(), a.neu)).collect()
    };
    let want = |k: &str| -> Vec<(String, String)> {
        g[k].as_array()
            .unwrap()
            .iter()
            .map(|p| (s(&p[0]).to_owned(), s(&p[1]).to_owned()))
            .collect()
    };
    assert_eq!(pairs(sdk_attribution_anchors()), want("anchors"));
    assert_eq!(pairs(sdk_summary_delta_anchors()), want("summaryAnchors"));
    assert_eq!(ATTRIBUTION_PRELOAD_SOURCE, s(&g["preload"]));
    assert_eq!(ATTRIBUTION_ENTRYPOINT_IMPORT, s(&g["entrypointImport"]));
    assert_eq!(STEER_RUN_MOUNT_OLD, s(&g["steerRunMountOld"]));
    assert_eq!(STEER_RUN_MOUNT_NEW, s(&g["steerRunMountNew"]));
    assert_eq!(NATIVE_AGENT_SKILLS_ASSIGN, s(&g["nativeAgentSkillsAssign"]));
    assert_eq!(STUB_AGENT_SKILLS_ASSIGN, s(&g["stubAgentSkillsAssign"]));
    assert_eq!(SDK_SUMMARY_DELTA_YIELD, s(&g["summaryDeltaYield"]));
    assert_eq!(summary_delta_patch_needle(), s(&g["summaryDeltaNeedle"]));
    assert_eq!(
        ATTRIBUTION_PROVIDER_MARKER,
        s(&g["attributionProviderMarker"])
    );
    assert_eq!(ATTRIBUTION_PRELOAD_REL, s(&g["attributionPreloadRel"]));
    assert_eq!(
        ATTRIBUTION_ENTRYPOINT_REL,
        s(&g["attributionEntrypointRel"])
    );
    assert_eq!(STEER_RUN_SERVER_REL, s(&g["steerRunServerRel"]));
    assert_eq!(crate::bridge::READY_PREFIX, s(&g["readyPrefix"]));

    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("a.json");
    write_attribution_config(&path, true, false).unwrap();
    assert_eq!(
        std::fs::read_to_string(path).unwrap(),
        s(&g["attributionConfig"])
    );
}

#[test]
fn context_table_matches_go() {
    let g = pkg();
    for row in g["limits"].as_array().unwrap() {
        let id = s(&row[0]);
        let l = limits_for(id);
        assert_eq!(
            (l.base, l.max, base_context_window(id), vendor(id)),
            (
                row[1].as_i64().unwrap(),
                row[2].as_i64().unwrap(),
                row[3].as_i64().unwrap(),
                s(&row[4])
            ),
            "{id:?}"
        );
    }
    let order: Vec<&str> = g["vendorOrder"].as_array().unwrap().iter().map(s).collect();
    assert_eq!(VENDOR_ORDER, order.as_slice());
}

#[test]
fn slugs_redaction_interactions_errors_match_go() {
    let g = pkg();
    for row in g["slugs"].as_array().unwrap() {
        assert_eq!(
            crate::cursor_project_slug(s(&row[0])),
            s(&row[1]),
            "{}",
            row[0]
        );
    }
    for row in g["redact"].as_array().unwrap() {
        assert_eq!(
            json_tail(&crate::bridge::redact_bridge_line(s(&row[0]))),
            json_tail(s(&row[1]))
        );
    }
    for row in g["interactions"].as_array().unwrap() {
        let (t, body) = parse_interaction_type(s(&row[0]));
        assert_eq!(
            (t.as_str(), body.as_str()),
            (s(&row[1]), s(&row[2])),
            "{}",
            row[0]
        );
    }
    for row in g["connectErrors"].as_array().unwrap() {
        let got = parse_connect_error(s(&row[0]).as_bytes());
        match (&row[1], got) {
            (Value::Null, None) => {}
            (want, Some(e)) if !want.is_null() => {
                assert_eq!(e.code, s(&want["code"]));
                assert_eq!(e.message, s(&want["message"]));
                assert_eq!(e.details, s(&want["details"]));
                assert_eq!(e.raw, s(&want["raw"]));
                assert_eq!(e.to_string(), s(&want["error"]));
                assert_eq!(e.transient(), want["transient"].as_bool().unwrap());
                assert_eq!(e.unauthenticated(), want["unauth"].as_bool().unwrap());
                assert_eq!(e.unimplemented(), want["unimpl"].as_bool().unwrap());
                assert_eq!(e.active_run_conflict(), want["conflict"].as_bool().unwrap());
            }
            (want, got) => panic!("{}: want {want}, got {got:?}", row[0]),
        }
    }
}

#[test]
fn agent_options_encode_like_go() {
    let g = pkg();
    let opts = AgentOptions {
        model: Some(ModelSelection {
            id: "composer-2.5".into(),
            params: vec![ModelParameterValue {
                id: "fast".into(),
                value: "true".into(),
            }],
        }),
        api_key: "sk".into(),
        name: "W-CO".into(),
        local: Some(LocalOptions {
            cwd: vec!["/tmp/wt".into()],
            setting_sources: SETTING_SOURCES_MINIMAL
                .iter()
                .map(|x| (*x).to_owned())
                .collect(),
            sandbox: Some(SandboxOptions { enabled: false }),
        }),
        mcp_servers: [
            (
                "recur".to_owned(),
                McpServer::http("http://x/tok/mcp?a=<b>&c"),
            ),
            (
                "fs".to_owned(),
                McpServer {
                    stdio: Some(StdioMcpServer {
                        command: "npx".into(),
                        args: vec!["-y".into()],
                        env: [
                            ("B".to_owned(), "2".to_owned()),
                            ("A".to_owned(), "1".to_owned()),
                        ]
                        .into(),
                        ..Default::default()
                    }),
                    ..Default::default()
                },
            ),
            (
                "lin".to_owned(),
                McpServer {
                    http: Some(HttpMcpServer {
                        kind: "HTTP_MCP_TRANSPORT_TYPE_HTTP".into(),
                        url: "https://l".into(),
                        headers: [("Authorization".to_owned(), "Bearer x".to_owned())].into(),
                    }),
                    ..Default::default()
                },
            ),
        ]
        .into(),
        mode: "plan".into(),
    };
    assert_eq!(
        serde_json::to_value(&opts).unwrap(),
        json_tail(s(&g["agentOptionsJSON"])).1
    );
    let minimal = AgentOptions {
        local: Some(LocalOptions {
            sandbox: Some(SandboxOptions { enabled: false }),
            ..Default::default()
        }),
        ..Default::default()
    };
    assert_eq!(
        serde_json::to_value(&minimal).unwrap(),
        json_tail(s(&g["minimalOptionsJSON"])).1
    );
}

#[test]
fn tool_mapping_matches_go() {
    let g = engine();
    for row in g["tools"].as_array().unwrap() {
        let (name, input) = (s(&row["name"]), s(&row["input"]));
        let d = crate::tools::display_tool(name, input);
        let got = json!({
            "canonical": crate::tools::canonical_tool(name),
            "toolInput": json_tail(&crate::tools::cursor_tool_input(name, input)),
            "displayName": d.name,
            "displayInput": json_tail(&d.input),
            "summary": recur_agent::display::summarize_tool_input(&d.name, &d.input),
        });
        let want = json!({
            "canonical": row["canonical"], "toolInput": json_tail(s(&row["toolInput"])),
            "displayName": row["displayName"], "displayInput": json_tail(s(&row["displayInput"])),
            "summary": row["summary"],
        });
        assert_eq!(got, want, "{name} {input}");
    }
    let p = crate::CursorProvider::new(Default::default());
    for row in g["results"].as_array().unwrap() {
        let (name, raw) = (s(&row["name"]), s(&row["raw"]));
        assert_eq!(
            crate::tools::cursor_tool_result_text(name, raw),
            s(&row["text"]),
            "{name} {raw}"
        );
        assert_eq!(
            recur_agent::display::display_tool_result(&p, name, raw),
            s(&row["display"]),
            "{name} {raw}"
        );
    }
}

#[test]
fn wire_prompts_match_go() {
    let g = engine();
    let imgs = vec![
        recur_agent::UserImage {
            id: "img_2".into(),
            mime: "image/png".into(),
            data: "BBBB".into(),
            ..Default::default()
        },
        recur_agent::UserImage {
            id: "img_1".into(),
            mime: "image/jpeg".into(),
            data: "AAAA".into(),
            ..Default::default()
        },
    ];
    let r =
        crate::runner::CursorRunner::new(crate::Bridge::bound("http://127.0.0.1:9", "", None), "");
    for row in g["wire"].as_array().unwrap() {
        let req = recur_agent::TurnRequest {
            system_prompt: s(&row["systemPrompt"]).into(),
            append_system_prompt: s(&row["appendSystemPrompt"]).into(),
            prompt: s(&row["prompt"]).into(),
            turn_append_prompt: s(&row["turnAppendPrompt"]).into(),
            chat_child: row["chatChild"].as_bool().unwrap(),
            allowed_tools: row["allowedTools"]
                .as_array()
                .map(|a| a.iter().map(|t| s(t).to_owned()).collect()),
            images: if row["images"].as_i64() == Some(2) {
                imgs.clone()
            } else {
                Vec::new()
            },
            ..Default::default()
        };
        assert_eq!(
            r.wire_prompt(&req, row["standing"].as_bool().unwrap()),
            s(&row["wire"]),
            "{row}"
        );
        let ids: Vec<String> = crate::runner::cursor_images(&req)
            .into_iter()
            .map(|i| format!("{}|{}", i.data, i.mime_type))
            .collect();
        let want: Vec<String> = row["imageIDs"]
            .as_array()
            .map(|a| a.iter().map(|x| s(x).to_owned()).collect())
            .unwrap_or_default();
        assert_eq!(ids, want);
    }
    let c = &g["constants"];
    assert_eq!(crate::turn::UNREPORTED_RESULT_TEXT, s(&c["unreported"]));
    assert_eq!(
        crate::turn::STEER_CANCELLED_CALL_TEXT,
        s(&c["steerCancelled"])
    );
    assert_eq!(crate::runner::CURSOR_SUBAGENT_PROMPT, s(&c["subagent"]));
    assert_eq!(
        crate::runner::CURSOR_CHILD_SUBAGENT_PROMPT,
        s(&c["childSubagent"])
    );
}

#[test]
fn meter_math_and_messages_match_go() {
    let g = engine();
    for row in g["expand"].as_array().unwrap() {
        assert_eq!(crate::turn::expand_cursor_run_error(s(&row[0])), s(&row[1]));
    }
    for row in g["scale"].as_array().unwrap() {
        let n: Vec<i64> = row
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_i64().unwrap())
            .collect();
        let mut u = recur_agent::TokenUsage {
            input_tokens: n[0],
            cache_read_tokens: n[1],
            cache_creation_tokens: n[2],
            output_tokens: 11,
            ..Default::default()
        };
        scale_cursor_meter_usage(&mut u, n[3], n[4]);
        assert_eq!(
            [
                u.input_tokens,
                u.cache_read_tokens,
                u.cache_creation_tokens,
                u.output_tokens
            ],
            [n[5], n[6], n[7], n[8]],
            "{row}"
        );
    }
    for row in g["noResult"].as_array().unwrap() {
        assert_eq!(
            crate::runner::cursor_no_result_message(s(&row[0]), " (bridge log: /tmp/b.log)"),
            s(&row[1])
        );
    }
}

fn dump_result(r: &recur_agent::TurnResult) -> Value {
    json!({
        "sessionId": r.session_id, "subtype": r.subtype, "isError": r.is_error, "durationMs": r.duration_ms,
        "text": r.text, "inputTokens": r.usage.input_tokens, "outputTokens": r.usage.output_tokens,
        "cacheCreationTokens": r.usage.cache_creation_tokens, "cacheReadTokens": r.usage.cache_read_tokens,
        "stderr": r.stderr,
    })
}

fn dump_event(e: &recur_agent::AgentEvent) -> Option<Value> {
    use recur_agent::AgentEvent as E;
    let mut m = json!({"kind": e.kind()});
    match e {
        E::Text { text, .. }
        | E::TextDelta { text, .. }
        | E::Thinking { text, .. }
        | E::ThinkingDelta { text, .. }
        | E::Notice { text } => {
            m["text"] = text.as_str().into();
        }
        E::Step(st) => {
            m["id"] = st.id.as_str().into();
            m["name"] = st.name.as_str().into();
            m["summary"] = st.summary.as_str().into();
            m["input"] = st.input.as_str().into();
        }
        E::ToolResult(r) => {
            m["id"] = r.id.as_str().into();
            m["name"] = r.name.as_str().into();
            m["text"] = r.text.as_str().into();
            m["isError"] = r.is_error.into();
            m["truncated"] = r.truncated.into();
        }
        E::Usage(u) => {
            m["result"] = dump_result(&recur_agent::TurnResult {
                usage: u.clone(),
                ..Default::default()
            });
        }
        E::Compact {
            status,
            trigger,
            summary,
            pre_tokens,
            ..
        } => {
            m["status"] = status.as_str().into();
            m["trigger"] = trigger.as_str().into();
            m["summary"] = summary.as_str().into();
            m["preTokens"] = (*pre_tokens).into();
        }
        E::TurnEnd(r) => m["result"] = dump_result(r),
        E::User {
            text,
            display,
            live_steer,
        } => {
            m["text"] = text.as_str().into();
            m["display"] = display.as_str().into();
            m["live"] = (*live_steer).into();
        }
        // Rust-only: the createPlan harvest the engine used to do by name.
        E::PlanProposal { .. } => return None,
        _ => {}
    }
    Some(m)
}

#[test]
fn frame_folds_match_go() {
    let g = engine();
    for (name, fold) in g["folds"].as_object().unwrap() {
        let flags: recur_agent::Flags = fold["flags"]
            .as_object()
            .map(|m| {
                m.iter()
                    .map(|(k, v)| (k.clone(), s(v).to_owned()))
                    .collect()
            })
            .unwrap_or_default();
        let rec = crate::turn::tests::Rec::default();
        let t = Turn::new(
            TurnSpec {
                model: s(&fold["model"]).into(),
                flags,
                include_partials: fold["partials"].as_bool().unwrap(),
            },
            Some(rec.sink()),
            "agent-1",
            false,
        );
        for f in fold["frames"].as_array().unwrap() {
            t.on_event(
                decode_frame(s(f).as_bytes()).unwrap_or_else(|| panic!("{name}: decode {f}")),
            );
        }
        t.finish();
        let got: Vec<Value> = rec.all().iter().filter_map(dump_event).collect();
        let want = fold["events"].as_array().cloned().unwrap_or_default();
        assert_eq!(got.len(), want.len(), "{name}: {got:#?}\nwant {want:#?}");
        for (i, (g, w)) in got.iter().zip(&want).enumerate() {
            assert_eq!(g, w, "{name} event {i}");
        }
        assert_eq!(dump_result(&t.result()), fold["result"], "{name} result");
        let ids: Vec<String> = fold["runIDs"]
            .as_array()
            .map(|a| a.iter().map(|v| s(v).to_owned()).collect())
            .unwrap_or_default();
        assert_eq!(t.all_run_ids(), ids, "{name} run ids");
    }
}
